import{_ as a,o as t,a as d,b as n}from"./app.UgfkfLuP.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"类型转换","link":"/api/SIMD-API/tensor_api/reg_vector_compute/type_conversion/type_conversion"},{"text":"舍入模式与饱和模式","link":"/api/SIMD-API/tensor_api/reg_vector_compute/type_conversion/rounding_mode"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/type_conversion/rounding_mode.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/type_conversion/rounding_mode.md","outlineHeaders":[{"level":2,"title":"概述","slug":"概述","link":"#概述"},{"level":2,"title":"舍入模式","slug":"舍入模式","link":"#舍入模式"},{"level":3,"title":"配置规则","slug":"配置规则","link":"#配置规则"},{"level":3,"title":"舍入过程举例","slug":"舍入过程举例","link":"#舍入过程举例"},{"level":2,"title":"饱和模式与非饱和模式","slug":"饱和模式与非饱和模式","link":"#饱和模式与非饱和模式"},{"level":3,"title":"配置方法","slug":"配置方法","link":"#配置方法"},{"level":4,"title":"按cast_options配置","slug":"按cast_options配置","link":"#按cast_options配置"},{"level":4,"title":"按全局CTRL配置","slug":"按全局CTRL配置","link":"#按全局CTRL配置"},{"level":3,"title":"模式对比","slug":"模式对比","link":"#模式对比"},{"level":3,"title":"整数转整数示例","slug":"整数转整数示例","link":"#整数转整数示例"},{"level":3,"title":"浮点转整数示例","slug":"浮点转整数示例","link":"#浮点转整数示例"},{"level":3,"title":"浮点转浮点示例","slug":"浮点转浮点示例","link":"#浮点转浮点示例"},{"level":2,"title":"配置示例","slug":"配置示例","link":"#配置示例"}],"lastUpdated":1793441129000}'),c={name:"api/SIMD-API/tensor_api/reg_vector_compute/type_conversion/rounding_mode.md"};function p(e,s,o,l,r,h){return t(),d("div",null,[...s[0]||(s[0]=[n(`<div><article class="markdown-body"><h1>舍入模式与饱和模式</h1><h2 id="概述">概述<a class="header-anchor" href="#概述">​</a></h2><p>Tensor API通过<code>cast</code>接口完成寄存器数据类型转换。对于可能发生精度损失或数值溢出的转换，可以通过编译期<code>cast_options</code>指定舍入模式和饱和模式：</p><ul><li><strong>舍入模式</strong>：指定精度损失时的舍入方向或规则。</li><li><strong>饱和模式</strong>：指定转换结果超出目的类型表示范围时的处理方式。</li></ul><p>相关接口声明位于<code>tensor_api/experimental/arch/vector/type_conversion.h</code>，相关枚举定义位于<code>tensor_api/experimental/utils/reg_enum.h</code>。</p><h2 id="舍入模式">舍入模式<a class="header-anchor" href="#舍入模式">​</a></h2><p><code>cast_round_mode</code>用于指定<code>cast</code>的舍入方式。Tensor API使用枚举值配置模式。</p><table><thead><tr><th>枚举值</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>rint</td><td>舍入到最近值；正好位于中间值时舍入到偶数。</td><td>1.5 → 2，2.5 → 2</td></tr><tr><td>round</td><td>舍入到最近值；正好位于中间值时远离0。</td><td>1.5 → 2，-1.5 → -2</td></tr><tr><td>floor</td><td>向负无穷方向舍入。</td><td>1.7 → 1，-1.3 → -2</td></tr><tr><td>ceil</td><td>向正无穷方向舍入。</td><td>1.3 → 2，-1.7 → -1</td></tr><tr><td>trunc</td><td>向0方向舍入，直接截断小数部分。</td><td>1.7 → 1，-1.7 → -1</td></tr><tr><td>odd</td><td>最近邻奇数舍入，舍入到最近的奇数。当前仅<code>float → half</code>支持该模式。</td><td>1.5 → 1</td></tr><tr><td>hybrid</td><td>混合舍入模式，当前用于<code>float</code>或<code>half</code>转换为<code>hifloat8_t</code>。</td><td>-</td></tr><tr><td>unknown</td><td>未指定舍入方式的预留值。仅在对应类型转换支持该配置时使用。</td><td>-</td></tr></tbody></table><h3 id="配置规则">配置规则<a class="header-anchor" href="#配置规则">​</a></h3><ul><li>表中<code>rint</code>、<code>round</code>、<code>floor</code>、<code>ceil</code>和<code>trunc</code>的示例以浮点转整数为例。浮点转浮点时，舍入目标是目的格式能够表示的数，而不是整数。</li><li>舍入模式是<code>cast</code>模板参数<code>opt</code>的一部分，在编译期确定。</li><li>不同源类型和目的类型支持的舍入模式不同，必须按照<a href="cast.html#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">cast的数据类型</a>表配置。</li><li>不支持的类型、布局、舍入和饱和配置组合会触发编译期错误。</li><li>对不会损失精度的精确扩宽转换，接口可能使用固定的<code>rint</code>配置，但不会额外改变数值。</li></ul><h3 id="舍入过程举例">舍入过程举例<a class="header-anchor" href="#舍入过程举例">​</a></h3><p>以下以范围内的<code>float → int16_t</code>转换为例，说明常用舍入模式对正数、负数和中间值的处理：</p><table><thead><tr><th>输入</th><th><code>rint</code></th><th><code>round</code></th><th><code>floor</code></th><th><code>ceil</code></th><th><code>trunc</code></th></tr></thead><tbody><tr><td>1.4</td><td>1</td><td>1</td><td>1</td><td>2</td><td>1</td></tr><tr><td>1.5</td><td>2</td><td>2</td><td>1</td><td>2</td><td>1</td></tr><tr><td>2.5</td><td>2</td><td>3</td><td>2</td><td>3</td><td>2</td></tr><tr><td>-1.4</td><td>-1</td><td>-1</td><td>-2</td><td>-1</td><td>-1</td></tr><tr><td>-1.5</td><td>-2</td><td>-2</td><td>-2</td><td>-1</td><td>-1</td></tr><tr><td>-2.5</td><td>-2</td><td>-3</td><td>-3</td><td>-2</td><td>-2</td></tr></tbody></table><p>其中，<code>rint</code>与<code>round</code>都选择最近值，但中间值的处理不同：<code>2.5</code>在<code>rint</code>模式下得到偶数<code>2</code>，在<code>round</code>模式下得到远离0的<code>3</code>。<code>floor</code>和<code>trunc</code>对负数的处理也不同：<code>-1.4</code>分别得到<code>-2</code>和<code>-1</code>。</p><p><code>odd</code>用于目的浮点格式的奇数舍入，不能套用上述整数取整表。例如，<code>1.5</code>能够由<code>half</code>精确表示，转换为<code>half</code>时不能将其解释为整数<code>1</code>或<code>3</code>。<code>hybrid</code>用于<code>hifloat8_t</code>相关转换的混合舍入，不应按固定的向上、向下或向0取整规则理解。</p><h2 id="饱和模式与非饱和模式">饱和模式与非饱和模式<a class="header-anchor" href="#饱和模式与非饱和模式">​</a></h2><p><code>cast_sat_mode</code>用于指定转换结果超出目的类型表示范围时的处理方式。</p><table><thead><tr><th>枚举值</th><th>说明</th></tr></thead><tbody><tr><td>not_sat</td><td>非饱和模式。整数窄化转换超出范围时按目的格式截断；浮点转换保留目的浮点格式支持的特殊值。</td></tr><tr><td>sat</td><td>饱和模式。转换结果超出目的类型范围时钳位到目的类型边界。</td></tr><tr><td>unknown</td><td>不配置饱和模式的预留值，仅用于对应类型转换支持该配置的场景。</td></tr></tbody></table><h3 id="配置方法">配置方法<a class="header-anchor" href="#配置方法">​</a></h3><p>开启饱和模式和非饱和模式时，需配置CTRL寄存器。通过<a href="../../../c_api/spr/asc_get_ctrl.html">asc_get_ctrl接口</a>保存当前值，仅修改所需比特位，并在相关计算结束后恢复原值。</p><table><thead><tr><th>CTRL比特位</th><th>作用</th><th>配置值</th></tr></thead><tbody><tr><td>CTRL[60]</td><td>选择单指令/API配置或全局饱和配置。</td><td>0：使用单指令/API配置；1：使用全局配置。</td></tr><tr><td>CTRL[59]</td><td>控制浮点转整数、整数转整数的全局转换饱和模式，仅在<code>CTRL[60] = 1</code>时生效。</td><td>0：饱和；1：截断。</td></tr><tr><td>CTRL[48]</td><td>控制浮点计算及部分浮点精度转换的全局饱和行为。</td><td>0：饱和，INF钳位到对应有限边界、NaN转换为0；1：非饱和，保留INF和NaN。</td></tr><tr><td>CTRL[50]</td><td>控制<code>fp8_e8m0_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>相关场景的全局饱和模式。</td><td>0：饱和；1：非饱和。</td></tr></tbody></table><h4 id="按cast_options配置">按cast_options配置<a class="header-anchor" href="#按cast_options配置">​</a></h4><p>希望通过<code>cast_options::sat</code>分别选择每条转换的饱和行为时，将<code>CTRL[60]</code>设置为<code>0</code>，再使用<code>cast_sat_mode::sat</code>或<code>cast_sat_mode::not_sat</code>调用<code>cast</code>。CTRL配置在SIMD VF外、执行相关转换之前完成；相关计算结束后恢复：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;c_api/spr/spr.h&quot;</span>

<span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">saved_ctrl</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">asc_get_ctrl</span><span class="p">());</span>
<span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">api_ctrl</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">saved_ctrl</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="o">~</span><span class="p">(</span><span class="kt">uint64_t</span><span class="p">{</span><span class="mi">1</span><span class="p">}</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="mi">60</span><span class="p">);</span>
<span class="n">asc_set_ctrl</span><span class="p">(</span><span class="n">api_ctrl</span><span class="p">);</span>
</code></pre></div><p>执行本页<a href="#%E9%85%8D%E7%BD%AE%E7%A4%BA%E4%BE%8B">配置示例</a>所示的寄存器转换后，在SIMD VF外恢复：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_set_ctrl</span><span class="p">(</span><span class="n">saved_ctrl</span><span class="p">);</span>
</code></pre></div><h4 id="按全局CTRL配置">按全局CTRL配置<a class="header-anchor" href="#按全局CTRL配置">​</a></h4><p>对于浮点转整数或整数转整数，若使用全局模式，将<code>CTRL[60]</code>设置为<code>1</code>，并通过<code>CTRL[59]</code>指定饱和或截断。以下为全局饱和模式的配置片段：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">saved_ctrl</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">asc_get_ctrl</span><span class="p">());</span>
<span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">global_sat_ctrl</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">saved_ctrl</span><span class="w"> </span><span class="o">|</span><span class="w"> </span><span class="p">(</span><span class="kt">uint64_t</span><span class="p">{</span><span class="mi">1</span><span class="p">}</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="mi">60</span><span class="p">))</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="o">~</span><span class="p">(</span><span class="kt">uint64_t</span><span class="p">{</span><span class="mi">1</span><span class="p">}</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="mi">59</span><span class="p">);</span>
<span class="n">asc_set_ctrl</span><span class="p">(</span><span class="n">global_sat_ctrl</span><span class="p">);</span>
</code></pre></div><p>若改为全局截断模式，则使用<code>asc_set_ctrl(global_sat_ctrl | (uint64_t{1} &lt;&lt; 59))</code>。全局模式下不能仅根据<code>cast_options::sat</code>判断最终饱和行为，且仍须传入该类型组合支持的<code>cast_options</code>。转换结束后同样使用<code>asc_set_ctrl(saved_ctrl)</code>恢复。</p><p>浮点转浮点场景应根据目的类型配置<code>CTRL[48]</code>及适用的<code>CTRL[50]</code>，不能用<code>CTRL[59]</code>代替。<code>FLOAT</code>全局饱和需要先启用全局策略；<code>FLOAT8</code>饱和还需要先启用<code>FLOAT</code>饱和。各模式的适用范围和配置约束请参考<a href="../../../c_api/spr/asc_set_ctrl.html">asc_set_ctrl</a>和<a href="../../../c_api/spr/asc_set_saturation_flag.html">asc_set_saturation_flag</a>。修改CTRL会影响当前核上其他受这些比特位控制的计算，不能直接写入一个固定值而覆盖无关配置。</p><h3 id="模式对比">模式对比<a class="header-anchor" href="#模式对比">​</a></h3><p>不同转换场景下的行为如下：</p><table><thead><tr><th>转换场景</th><th><code>not_sat</code></th><th><code>sat</code></th></tr></thead><tbody><tr><td>浮点转整数</td><td>超出范围时按目的格式截断；正负无穷返回目的类型对应边界值；NaN返回0。</td><td>超出范围时返回目的类型边界值；正负无穷分别钳位到对应边界；NaN返回0。</td></tr><tr><td>浮点转浮点</td><td>目的类型支持时保留NaN和正负无穷；有限值超出范围时按目的浮点格式转换。</td><td>超出范围时钳位到目的浮点类型边界；NaN转换为0。</td></tr><tr><td>整数转浮点</td><td>该场景不提供饱和模式，使用舍入模式控制可能的精度损失。</td><td>不支持。</td></tr><tr><td>整数转整数</td><td>窄化转换超出范围时截断为目的格式的数据宽度；扩宽转换通常保持数值。</td><td>超出范围时钳位到目的类型边界。</td></tr></tbody></table><p>例如，<code>int32_t</code>转换为<code>uint8_t</code>时，输入<code>256</code>在<code>not_sat</code>模式下结果为<code>0</code>，在<code>sat</code>模式下结果为<code>255</code>；输入<code>-1</code>在<code>sat</code>模式下结果为<code>0</code>。</p><h3 id="整数转整数示例">整数转整数示例<a class="header-anchor" href="#整数转整数示例">​</a></h3><p>以<code>int32_t → uint8_t</code>为例，非饱和模式保留低8 bit，而不是将数值钳位到范围内：</p><table><thead><tr><th>输入</th><th>非饱和结果</th><th>饱和结果</th></tr></thead><tbody><tr><td>100</td><td>100</td><td>100</td></tr><tr><td>256（0x00000100）</td><td>0（0x00）</td><td>255</td></tr><tr><td>511（0x000001FF）</td><td>255（0xFF）</td><td>255</td></tr><tr><td>-1（0xFFFFFFFF）</td><td>255（0xFF）</td><td>0</td></tr></tbody></table><p>扩宽转换通常保持数值，但不能据此推断任意有符号到无符号转换。例如，<code>int16_t → uint32_t</code>要求<code>opt.sat</code>为<code>not_sat</code>，底层转换仍采用饱和语义，负数转换为<code>0</code>。请以<a href="cast.html#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">cast的数据类型说明</a>和对应转换约束为准。</p><h3 id="浮点转整数示例">浮点转整数示例<a class="header-anchor" href="#浮点转整数示例">​</a></h3><p>以<code>float → int16_t</code>为例，先按所选舍入模式处理小数部分，再按有效的饱和配置处理超出目的类型范围的结果。下表使用<code>rint</code>：</p><table><thead><tr><th>输入</th><th>非饱和结果</th><th>饱和结果</th></tr></thead><tbody><tr><td>2.5</td><td>2</td><td>2</td></tr><tr><td>40000.0</td><td>-25536，保留低16 bit</td><td>32767</td></tr><tr><td>-40000.0</td><td>25536，保留低16 bit</td><td>-32768</td></tr><tr><td>正无穷</td><td>32767</td><td>32767</td></tr><tr><td>负无穷</td><td>-32768</td><td>-32768</td></tr><tr><td>NaN</td><td>0</td><td>0</td></tr></tbody></table><h3 id="浮点转浮点示例">浮点转浮点示例<a class="header-anchor" href="#浮点转浮点示例">​</a></h3><p>以<code>float → half</code>为例，目的类型最大有限正数为<code>65504.0</code>。下表使用<code>rint</code>，并假设CTRL已按对应模式配置：</p><table><thead><tr><th>输入</th><th>非饱和结果</th><th>饱和结果</th></tr></thead><tbody><tr><td>1.5</td><td>1.5</td><td>1.5</td></tr><tr><td>70000.0</td><td>正无穷</td><td>65504.0</td></tr><tr><td>-70000.0</td><td>负无穷</td><td>-65504.0</td></tr><tr><td>正无穷</td><td>正无穷</td><td>65504.0</td></tr><tr><td>负无穷</td><td>负无穷</td><td>-65504.0</td></tr><tr><td>NaN</td><td>NaN</td><td>0</td></tr></tbody></table><p>上述结果不能推广到所有低精度浮点格式或所有舍入模式。其他目的格式对NaN、无穷和有限溢出值的处理，以对应类型转换的约束为准。</p><h2 id="配置示例">配置示例<a class="header-anchor" href="#配置示例">​</a></h2><p>以下片段在SIMD VF或SIMD被调函数内将<code>float</code>转换为<code>half</code>，使用向最近偶数舍入和饱和模式。<code>src</code>为已完成数据和mask初始化的<code>reg_tensor&lt;float&gt;</code>，调用前须按<a href="#%E9%85%8D%E7%BD%AE%E6%96%B9%E6%B3%95">配置方法</a>设置CTRL饱和策略：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">cast_options</span><span class="w"> </span><span class="n">options</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">cast_layout</span><span class="o">::</span><span class="n">zero</span><span class="p">,</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">cast_round_mode</span><span class="o">::</span><span class="n">rint</span><span class="p">,</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">cast_sat_mode</span><span class="o">::</span><span class="n">sat</span><span class="p">,</span>
<span class="p">};</span>

<span class="k">auto</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">cast</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">options</span><span class="o">&gt;</span><span class="p">(</span><span class="n">src</span><span class="p">);</span>
</code></pre></div><p><code>cast_layout</code>用于描述源、目的类型位宽不同时较小元素在寄存器中的位置，不属于舍入或饱和模式。具体布局要求请参考<a href="../aux_data_types/cast_layout.html">cast_layout</a>。</p></article></div>`,1)])])}const v=a(c,[["render",p]]);export{_ as __pageData,v as default};
